# Video.Statuses.PUBLISHED, copied: a migration must not import the live model.
PUBLISHED = 5


def mark_sent_notifications(apps, schema_editor):
    """Without the flags the next status update would announce old acceptances and videos."""
    Request = apps.get_model("video_requests", "Request")
    Video = apps.get_model("video_requests", "Video")

    for request in Request.objects.filter(additional_data__accepted=True):
        request.additional_data["accepted_notification_sent"] = True
        request.save(update_fields=["additional_data"])

    for video in Video.objects.filter(status__gte=PUBLISHED):
        video.additional_data.setdefault("publishing", {})[
            "notification_sent_to_user"
        ] = True
        video.save(update_fields=["additional_data"])


